using System;using System.Collections.Generic;using KNL;using UnityEngine;
class CloudController:MonoBehaviour { public int maxClouds=160;public int initialized=-1;void Awake(){initialized=maxClouds;} }
class UnknownCloudController:MonoBehaviour { public int maxClouds=160; }
namespace ParticlePlayground {
 public class Consumer { public List<object> events=new List<object>();public List<Consumer> manipulators=new List<Consumer>();public bool trackParticles;public Action particleEventBirth; }
 public class PlaygroundC:MonoBehaviour { public static Action particleEventBirth;public List<Consumer> particleSystems=new List<Consumer>();public List<Consumer> manipulators=new List<Consumer>();public static int clock;public int original;public bool started;public static void SetTime(){clock++;}void Start(){started=true;}void LateUpdate(){original++;} }
}
class VisualQualityRegression {
 static int count;static void Check(bool yes,string name){if(!yes)throw new Exception(name);Console.WriteLine("PASS: "+name);count++;}
 static void Main(){World.ActiveScene=new SceneTag("visuals");Environment.SetEnvironmentVariable("KNL_VISUALS","full");var manager=new GameObject("particles").AddComponent<ParticlePlayground.PlaygroundC>();Lifecycle.Frame(.02f);Check(manager.started&&manager.original==1,"full mode retains initialization and simulation");Environment.SetEnvironmentVariable("KNL_VISUALS","lite");Lifecycle.Frame(.02f);Check(manager.original==1&&ParticlePlayground.PlaygroundC.clock==1,"lite advances cosmetic clock without particle calculation");ParticlePlayground.PlaygroundC.particleEventBirth=()=>{};Lifecycle.Frame(.02f);Check(manager.original==2,"new manager callback immediately restores simulation");ParticlePlayground.PlaygroundC.particleEventBirth=null;var emitter=new ParticlePlayground.Consumer();manager.particleSystems.Add(emitter);emitter.events.Add(new object());Lifecycle.Frame(.02f);Check(manager.original==3,"serialized particle events preserve simulation");emitter.events.Clear();var manipulator=new ParticlePlayground.Consumer();emitter.manipulators.Add(manipulator);manipulator.trackParticles=true;Lifecycle.Frame(.02f);Check(manager.original==4,"tracked manipulator particles preserve simulation");manipulator.trackParticles=false;manipulator.particleEventBirth=()=>{};Lifecycle.Frame(.02f);Check(manager.original==5,"local manipulator callbacks preserve simulation");manipulator.particleEventBirth=null;Lifecycle.Frame(.02f);Check(manager.original==5&&ParticlePlayground.PlaygroundC.clock==2,"unconsumed decorative manipulators can skip work");Environment.SetEnvironmentVariable("KNL_VISUALS","full");Lifecycle.Frame(.02f);Check(manager.original==6,"switching back restores original simulation");Environment.SetEnvironmentVariable("KNL_VISUALS","lite");var cum=new GameObject("CloudsCumulus").AddComponent<CloudController>();Check(cum.initialized==12,"lite limits cumulii before original initialization");var fog=new GameObject("Fogs").AddComponent<CloudController>();Check(fog.initialized==0,"lite prevents fog sprite creation at initialization");var mist=new GameObject("Mists").AddComponent<CloudController>();Check(mist.initialized==0,"lite prevents foreground mist sheets at initialization");var ice=new GameObject("IceFloes").AddComponent<CloudController>();Check(ice.initialized==160,"winter ice decoration retains original budget");var stratus=new GameObject("CloudsStratus").AddComponent<CloudController>();Check(stratus.initialized==4,"lite keeps a small stratus decoration budget");var unknown=new GameObject("Unknown decoration").AddComponent<CloudController>();Check(unknown.initialized==160,"unknown cloud controller objects preserve original settings");var other=new GameObject("CloudsCumulus").AddComponent<UnknownCloudController>();VisualQuality.BeforeAwake(other);Check(other.maxClouds==160,"unrecognized component types remain untouched");var asm=AppDomain.CurrentDomain.DefineDynamicAssembly(new System.Reflection.AssemblyName("missingCloudField"),System.Reflection.Emit.AssemblyBuilderAccess.Run);var mod=asm.DefineDynamicModule("test");var tb=mod.DefineType("CloudController",System.Reflection.TypeAttributes.Public,typeof(MonoBehaviour));tb.DefineDefaultConstructor(System.Reflection.MethodAttributes.Public);var missing=(MonoBehaviour)Activator.CreateInstance(tb.CreateType());VisualQuality.BeforeAwake(missing);Check(true,"missing cloud field safely preserves original dispatch");Environment.SetEnvironmentVariable("KNL_VISUALS","full");var fullCloud=new GameObject("CloudsCumulus").AddComponent<CloudController>();Check(fullCloud.initialized==160,"full mode retains the authored cloud budget");Color top,bottom;VisualQuality.WaterColors(new Color(.1f,.2f,.3f,.1f),new Color(.4f,.5f,.6f,1),out top,out bottom);Check(top.a==1&&bottom.a==1&&top.r>bottom.r&&top.b>bottom.b,"simple water remains opaque with a depth gradient");Console.WriteLine("Visual regressions passed: "+count);}
}
